// @generated by project-forge — visual-layout.mjs (pure deterministic SVG/HTML layout model)
import { buildFallbackDomains } from './feature-map-graph.mjs'

export const DIFF_STATES = Object.freeze(['added', 'modified', 'impacted', 'context'])

const DOMAIN_PALETTES = Object.freeze([
  { id: 'teal', stroke: '#1b5e6b', fill: 'rgba(27,94,107,0.045)', badge: '#1b5e6b' },
  { id: 'moss', stroke: '#3f6a4f', fill: 'rgba(63,106,79,0.045)', badge: '#3f6a4f' },
  { id: 'ochre', stroke: '#8c6239', fill: 'rgba(140,98,57,0.045)', badge: '#8c6239' },
  { id: 'steel', stroke: '#355c7d', fill: 'rgba(53,92,125,0.045)', badge: '#355c7d' },
  { id: 'plum', stroke: '#6b4c5b', fill: 'rgba(107,76,91,0.045)', badge: '#6b4c5b' },
  { id: 'sage', stroke: '#4b5c58', fill: 'rgba(75,92,88,0.045)', badge: '#4b5c58' },
])

export function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

export function escapeXml(value) {
  return escapeHtml(value)
}

export function escapeJsonForScript(obj) {
  return JSON.stringify(obj)
    .replace(/</g, '\\u003c')
    .replace(/>/g, '\\u003e')
    .replace(/&/g, '\\u0026')
    .replace(/\u2028/g, '\\u2028')
    .replace(/\u2029/g, '\\u2029')
}

export function toRelPath(rawPath) {
  let p = String(rawPath ?? '').trim()
  if (!p) return ''
  p = p.replace(/^file:\/\/\/?/i, '')
  p = p.replace(/\\/g, '/')
  p = p.replace(/^[a-zA-Z]:\/(?:Users|Documents and Settings)\/[^/]+\//i, '')
  p = p.replace(/^\/(?:Users|home)\/[^/]+\//i, '')
  p = p.replace(/^[a-zA-Z]:\//, '')
  p = p.replace(/^\/+/, '')
  p = p.replace(/^\.\//, '')
  return p
}

export function sanitizeSafeHref(rawUrl) {
  const s = String(rawUrl ?? '').trim()
  if (!s) return ''
  const compact = s.replace(/[\u0000-\u0020]+/g, '')
  const schemeMatch = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(compact)
  if (!schemeMatch) {
    if (compact.startsWith('//')) return ''
    return toRelPath(s) || s
  }
  const scheme = schemeMatch[1].toLowerCase()
  if (scheme === 'http' || scheme === 'https' || scheme === 'file') return s
  return ''
}

export function sanitizeSafeImgSrc(rawSrc) {
  const s = String(rawSrc ?? '').trim()
  if (!s) return ''
  const compact = s.replace(/[\u0000-\u0020]+/g, '')
  if (/^data:image\/(?:png|jpeg|jpg|webp|gif);base64,[a-zA-Z0-9+/=]+$/i.test(compact)) {
    return compact
  }
  return sanitizeSafeHref(s)
}

function normArray(list) {
  return Array.isArray(list) ? list.map((x) => String(x ?? '').trim()).filter(Boolean) : []
}

function normRelArray(list) {
  return normArray(list).map(toRelPath).filter(Boolean)
}

const FULLWIDTH_CHAR_RE = /[\u1100-\u115f\u2e80-\ua4cf\uac00-\ud7a3\uf900-\ufaff\ufe10-\ufe19\ufe30-\ufe6f\uff00-\uff60\uffe0-\uffe6]/

function charDisplayWidth(ch) {
  return FULLWIDTH_CHAR_RE.test(ch) ? 2 : 1
}

export function truncateLabel(text, maxWidth = 28) {
  const s = String(text ?? '').trim()
  let total = 0
  for (const ch of s) total += charDisplayWidth(ch)
  if (total <= maxWidth) return s
  const budget = Math.max(4, maxWidth - 3)
  let acc = 0
  let out = ''
  for (const ch of s) {
    const w = charDisplayWidth(ch)
    if (acc + w > budget) break
    out += ch
    acc += w
  }
  return `${out}...`
}

function normalizeVerifyTools(rawTools) {
  if (!Array.isArray(rawTools)) return []
  return rawTools
    .map((t) => {
      if (typeof t === 'string') return t.trim()
      if (t && typeof t === 'object') {
        const id = String(t.id || t.name || '').trim()
        const cmd = String(t.command || t.scriptPath || '').trim()
        return id && cmd ? `${id}: ${cmd}` : (id || cmd)
      }
      return ''
    })
    .filter(Boolean)
}

function normalizeFeatures(featureMap) {
  const rawList = Array.isArray(featureMap?.features) ? featureMap.features : []
  return rawList
    .filter((f) => f && typeof f === 'object')
    .map((f, idx) => {
      const id = String(f.id || `feature-${idx + 1}`).trim()
      const businessFlows = normArray(f.businessFlows)
      const description = String(f.description || f.summary || businessFlows[0] || '').trim()
      return {
        id,
        title: String(f.title || f.name || id).trim(),
        description,
        businessFlows,
        domain: String(f.domain || '').trim(),
        risk: String(f.risk || 'medium').trim().toLowerCase(),
        status: String(f.status || 'active').trim().toLowerCase(),
        entrypoints: normRelArray(f.entrypoints),
        modules: normRelArray(f.modules || f.files),
        tests: normRelArray(Array.isArray(f.tests) && f.tests.length > 0 ? f.tests : f.testRefs),
        symbols: normArray(f.symbols),
        verifyTools: normalizeVerifyTools(Array.isArray(f.verificationTools) && f.verificationTools.length > 0 ? f.verificationTools : f.verifyTools),
        docAnchors: normArray(f.docAnchors),
        dependsOn: normArray(f.dependsOn),
        actors: normArray(f.actors),
        anchorLine: Number.isFinite(Number(f.anchorLine)) ? Number(f.anchorLine) : 1,
      }
    })
    .sort((a, b) => a.id.localeCompare(b.id))
}

function resolveDomains(featureMap, features) {
  const hasExplicit = Array.isArray(featureMap?.domains) && featureMap.domains.length > 0
  const fallback = hasExplicit ? null : buildFallbackDomains(features)
  const explicitDomains = hasExplicit
    ? featureMap.domains
    : (Array.isArray(fallback) ? fallback : (Array.isArray(fallback?.domains) ? fallback.domains : []))
  const domainMap = new Map()
  for (const d of explicitDomains) {
    if (!d || typeof d !== 'object') continue
    const id = String(d.id || 'core').trim()
    if (!id || domainMap.has(id)) continue
    domainMap.set(id, {
      id,
      title: String(d.title || d.name || id).trim(),
      description: String(d.description || '').trim(),
      risk: String(d.risk || 'medium').trim().toLowerCase(),
      owner: String(d.owner || '').trim(),
      featureIds: normArray(d.features),
    })
  }
  const assigned = new Set()
  for (const f of features) {
    const domId = f.domain && domainMap.has(f.domain)
      ? f.domain
      : (Array.from(domainMap.values()).find((d) => d.featureIds.includes(f.id))?.id || 'core')
    if (!domainMap.has(domId)) {
      domainMap.set(domId, {
        id: domId,
        title: domId,
        description: 'Synthesized domain group',
        risk: 'medium',
        owner: '',
        featureIds: [],
      })
    }
    const dom = domainMap.get(domId)
    if (!dom.featureIds.includes(f.id)) dom.featureIds.push(f.id)
    f.domain = domId
    assigned.add(f.id)
  }
  const result = Array.from(domainMap.values())
    .map((d, idx) => ({
      ...d,
      featureIds: d.featureIds.filter((fid) => assigned.has(fid)).sort(),
      palette: DOMAIN_PALETTES[idx % DOMAIN_PALETTES.length],
    }))
    .filter((d) => d.featureIds.length > 0 || explicitDomains.some((ed) => ed?.id === d.id))
    .sort((a, b) => a.id.localeCompare(b.id))
  return result
}

export function computeDiffOverlay(featureMap, diffOverlay = {}) {
  const features = normalizeFeatures(featureMap)
  const states = new Map()
  const directStates = diffOverlay?.featureStates && typeof diffOverlay.featureStates === 'object'
    ? diffOverlay.featureStates
    : {}
  const addedSet = new Set(normArray(diffOverlay?.added))
  const modifiedSet = new Set(normArray(diffOverlay?.modified))
  const impactedSet = new Set(normArray(diffOverlay?.impacted))
  const changedFiles = new Set(normRelArray(diffOverlay?.changedFiles))

  for (const f of features) {
    let state = 'context'
    const explicit = directStates[f.id]
    if (DIFF_STATES.includes(explicit)) {
      state = explicit
    } else if (addedSet.has(f.id)) {
      state = 'added'
    } else if (modifiedSet.has(f.id)) {
      state = 'modified'
    } else if (impactedSet.has(f.id)) {
      state = 'impacted'
    } else if (changedFiles.size > 0) {
      const ownedPaths = [...f.entrypoints, ...f.modules, ...f.tests]
      if (ownedPaths.some((p) => changedFiles.has(p))) {
        state = 'modified'
      }
    }
    states.set(f.id, state)
  }

  const dependents = new Map()
  for (const f of features) {
    for (const dep of f.dependsOn) {
      if (!dependents.has(dep)) dependents.set(dep, [])
      dependents.get(dep).push(f.id)
    }
  }

  const frontier = []
  for (const [fid, st] of states.entries()) {
    if (st === 'added' || st === 'modified') frontier.push(fid)
  }
  const visited = new Set(frontier)
  while (frontier.length > 0) {
    const cur = frontier.shift()
    const nextIds = dependents.get(cur) || []
    for (const nid of nextIds) {
      if (visited.has(nid)) continue
      visited.add(nid)
      if (states.get(nid) === 'context') {
        states.set(nid, 'impacted')
      }
      frontier.push(nid)
    }
  }

  const counts = { added: 0, modified: 0, impacted: 0, context: 0 }
  for (const st of states.values()) {
    counts[st] = (counts[st] || 0) + 1
  }
  return { states, counts, hasActiveDiff: counts.added + counts.modified + counts.impacted > 0 }
}

export function layoutDomainTree(featureMap, overlay, _opts = {}) {
  const features = normalizeFeatures(featureMap)
  const domains = resolveDomains(featureMap, features)
  const featureById = new Map(features.map((f) => [f.id, f]))
  const stateMap = overlay?.states instanceof Map ? overlay.states : new Map()

  const cardW = 264
  const cardH = 104
  const cardGapX = 22
  const cardGapY = 20
  const domPadX = 24
  const domHeaderH = 50
  const domPadBottom = 24
  const domGapX = 34
  const domGapY = 34
  const canvasPad = 32

  const domCols = domains.length <= 1 ? 1 : domains.length <= 4 ? 2 : 3
  const domainBoxes = []
  const featureBoxes = []
  const featureBoxMap = new Map()

  const preppedDomains = domains.map((dom) => {
    const items = dom.featureIds.map((fid) => featureById.get(fid)).filter(Boolean)
    const innerCols = items.length <= 1 ? 1 : Math.min(2, items.length)
    const rows = Math.max(1, Math.ceil(items.length / innerCols))
    const w = domPadX * 2 + innerCols * cardW + Math.max(0, innerCols - 1) * cardGapX
    const h = domHeaderH + rows * cardH + Math.max(0, rows - 1) * cardGapY + domPadBottom
    return { dom, items, innerCols, w, h }
  })

  const colWidths = Array.from({ length: domCols }, () => 0)
  preppedDomains.forEach((pd, idx) => {
    const col = idx % domCols
    colWidths[col] = Math.max(colWidths[col], pd.w)
  })

  const rowHeights = []
  preppedDomains.forEach((pd, idx) => {
    const row = Math.floor(idx / domCols)
    rowHeights[row] = Math.max(rowHeights[row] || 0, pd.h)
  })

  const colOffsets = []
  let accX = canvasPad
  for (let c = 0; c < domCols; c++) {
    colOffsets[c] = accX
    accX += colWidths[c] + domGapX
  }

  const rowOffsets = []
  let accY = canvasPad
  for (let r = 0; r < rowHeights.length; r++) {
    rowOffsets[r] = accY
    accY += rowHeights[r] + domGapY
  }

  preppedDomains.forEach((pd, idx) => {
    const col = idx % domCols
    const row = Math.floor(idx / domCols)
    const x = colOffsets[col]
    const y = rowOffsets[row]
    const w = colWidths[col]
    const h = pd.h
    domainBoxes.push({
      id: pd.dom.id,
      title: pd.dom.title,
      shortTitle: truncateLabel(pd.dom.title, 32),
      description: pd.dom.description,
      risk: pd.dom.risk,
      palette: pd.dom.palette,
      x,
      y,
      w,
      h,
      featureCount: pd.items.length,
    })

    pd.items.forEach((feat, fIdx) => {
      const fCol = fIdx % pd.innerCols
      const fRow = Math.floor(fIdx / pd.innerCols)
      const fx = x + domPadX + fCol * (cardW + cardGapX)
      const fy = y + domHeaderH + fRow * (cardH + cardGapY)
      const diffState = stateMap.get(feat.id) || 'context'
      const primaryAnchor = feat.entrypoints[0] || feat.modules[0] || feat.tests[0] || ''
      const summarySrc = feat.description || feat.businessFlows[0] || toRelPath(primaryAnchor) || feat.id
      const box = {
        ...feat,
        shortTitle: truncateLabel(feat.title, diffState !== 'context' ? 22 : 28),
        shortSummary: truncateLabel(summarySrc, 32),
        shortAnchor: truncateLabel(toRelPath(primaryAnchor) || feat.id, 32),
        domainTitle: pd.dom.title,
        x: fx,
        y: fy,
        w: cardW,
        h: cardH,
        cx: fx + cardW / 2,
        cy: fy + cardH / 2,
        diffState,
        primaryAnchor,
        palette: pd.dom.palette,
      }
      featureBoxes.push(box)
      featureBoxMap.set(feat.id, box)
    })
  })

  const edges = []
  for (const feat of featureBoxes) {
    for (const depId of feat.dependsOn) {
      const src = featureBoxMap.get(depId)
      if (!src || src.id === feat.id) continue
      const x1 = src.x + src.w
      const y1 = src.cy
      const x2 = feat.x
      const y2 = feat.cy
      const sameColRightToLeft = Math.abs(src.x - feat.x) < 10
      let pathD
      if (sameColRightToLeft) {
        const sy1 = src.y + src.h
        const sy2 = feat.y
        const midY = (sy1 + sy2) / 2
        pathD = `M ${src.cx} ${sy1} C ${src.cx} ${midY}, ${feat.cx} ${midY}, ${feat.cx} ${sy2}`
      } else if (src.x <= feat.x) {
        const dx = Math.max(40, Math.abs(x2 - x1) * 0.45)
        pathD = `M ${x1} ${y1} C ${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`
      } else {
        const sx1 = src.x
        const sx2 = feat.x + feat.w
        const dx = Math.max(40, Math.abs(sx2 - sx1) * 0.45)
        pathD = `M ${sx1} ${y1} C ${sx1 - dx} ${y1}, ${sx2 + dx} ${y2}, ${sx2} ${y2}`
      }
      edges.push({
        id: `${src.id}->${feat.id}`,
        fromId: src.id,
        toId: feat.id,
        pathD,
        impacted: src.diffState !== 'context' || feat.diffState !== 'context',
      })
    }
  }

  const width = Math.max(640, accX - domGapX + canvasPad)
  const height = Math.max(360, accY - domGapY + canvasPad)
  return { width, height, domains: domainBoxes, nodes: featureBoxes, edges }
}

function computeTopologicalRanks(nodes, edgePairs) {
  const rank = new Map(nodes.map((n) => [n.id, 0]))
  const indeg = new Map(nodes.map((n) => [n.id, 0]))
  const adj = new Map(nodes.map((n) => [n.id, []]))
  for (const [fromId, toId] of edgePairs) {
    if (!adj.has(fromId) || !adj.has(toId) || fromId === toId) continue
    adj.get(fromId).push(toId)
    indeg.set(toId, (indeg.get(toId) || 0) + 1)
  }
  const queue = nodes.filter((n) => (indeg.get(n.id) || 0) === 0).map((n) => n.id)
  const visited = new Set()
  while (queue.length > 0) {
    const cur = queue.shift()
    if (visited.has(cur)) continue
    visited.add(cur)
    const curRank = rank.get(cur) || 0
    for (const nxt of adj.get(cur) || []) {
      rank.set(nxt, Math.max(rank.get(nxt) || 0, curRank + 1))
      const nextIn = (indeg.get(nxt) || 0) - 1
      indeg.set(nxt, nextIn)
      if (nextIn <= 0) queue.push(nxt)
    }
  }
  for (const n of nodes) {
    if (!visited.has(n.id)) {
      rank.set(n.id, Math.min(4, (rank.get(n.id) || 0) + 1))
    }
  }
  return rank
}

export function layoutFlowDag(featureMap, overlay, _opts = {}) {
  const features = normalizeFeatures(featureMap)
  const domains = resolveDomains(featureMap, features)
  const stateMap = overlay?.states instanceof Map ? overlay.states : new Map()
  const rawFlows = Array.isArray(featureMap?.flows) ? featureMap.flows : []

  const laneSpecs = []
  const flowSummaries = []
  if (rawFlows.length > 0) {
    const laneNames = new Map()
    for (const fl of rawFlows) {
      if (!fl || typeof fl !== 'object') continue
      const flowId = String(fl.id || `flow-${flowSummaries.length + 1}`).trim()
      const flowTitle = String(fl.title || fl.name || flowId).trim()
      const steps = Array.isArray(fl.steps) ? fl.steps : []
      const cleanSteps = steps
        .map((step, sIdx) => ({
          stepIndex: sIdx + 1,
          feature: String(step?.feature || '').trim(),
          actor: String(step?.actor || step?.lane || 'system').trim(),
          action: String(step?.action || '').trim(),
        }))
        .filter((s) => s.feature)
      flowSummaries.push({
        id: flowId,
        title: flowTitle,
        description: String(fl.description || '').trim(),
        stepCount: cleanSteps.length,
        actors: normArray(fl.actors),
        featureIds: normArray(fl.features),
        steps: cleanSteps,
      })
      for (const step of steps) {
        const actor = String(step?.actor || step?.lane || 'system').trim()
        if (!laneNames.has(actor)) laneNames.set(actor, { id: actor, title: actor })
      }
    }
    for (const l of laneNames.values()) laneSpecs.push(l)
  }

  if (laneSpecs.length === 0) {
    for (const d of domains) {
      laneSpecs.push({ id: d.id, title: d.title, palette: d.palette })
    }
  }
  if (laneSpecs.length === 0) {
    laneSpecs.push({ id: 'core', title: 'Core Pipeline', palette: DOMAIN_PALETTES[0] })
  }

  const featureIds = new Set(features.map((f) => f.id))
  const edgePairs = []
  for (const f of features) {
    for (const dep of f.dependsOn) {
      if (featureIds.has(dep) && dep !== f.id) edgePairs.push([dep, f.id])
    }
  }
  const ranks = computeTopologicalRanks(features, edgePairs)
  const maxRank = Math.max(0, ...Array.from(ranks.values()))

  const labelColW = 172
  const nodeW = 200
  const nodeH = 74
  const colGap = 54
  const nodeGapY = 16
  const lanePadY = 18
  const pad = 24

  const laneBuckets = new Map(laneSpecs.map((l) => [l.id, []]))
  const fallbackLaneId = laneSpecs[0].id
  for (const f of features) {
    const preferredActor = f.actors[0]
    const targetLane = (preferredActor && laneBuckets.has(preferredActor))
      ? preferredActor
      : (laneBuckets.has(f.domain) ? f.domain : fallbackLaneId)
    laneBuckets.get(targetLane).push(f)
  }

  const lanes = []
  const flowNodes = []
  const flowNodeMap = new Map()
  let curY = pad

  laneSpecs.forEach((lane, laneIdx) => {
    const items = laneBuckets.get(lane.id) || []
    const byRank = new Map()
    for (const item of items) {
      const r = ranks.get(item.id) || 0
      if (!byRank.has(r)) byRank.set(r, [])
      byRank.get(r).push(item)
    }
    const maxStack = Math.max(1, ...Array.from(byRank.values()).map((arr) => arr.length))
    const laneH = lanePadY * 2 + maxStack * nodeH + Math.max(0, maxStack - 1) * nodeGapY
    const totalW = labelColW + (maxRank + 1) * nodeW + maxRank * colGap + pad * 2
    const palette = lane.palette || DOMAIN_PALETTES[laneIdx % DOMAIN_PALETTES.length]
    lanes.push({
      id: lane.id,
      title: lane.title,
      shortTitle: truncateLabel(lane.title, 20),
      x: pad,
      y: curY,
      w: totalW,
      h: laneH,
      labelW: labelColW,
      palette,
    })

    for (const [r, group] of byRank.entries()) {
      group.forEach((feat, stackIdx) => {
        const nx = pad + labelColW + 20 + r * (nodeW + colGap)
        const ny = curY + lanePadY + stackIdx * (nodeH + nodeGapY)
        const node = {
          id: feat.id,
          title: feat.title,
          shortTitle: truncateLabel(feat.title, 22),
          laneId: lane.id,
          rank: r,
          x: nx,
          y: ny,
          w: nodeW,
          h: nodeH,
          cx: nx + nodeW / 2,
          cy: ny + nodeH / 2,
          diffState: stateMap.get(feat.id) || 'context',
          palette,
        }
        flowNodes.push(node)
        flowNodeMap.set(feat.id, node)
      })
    }
    curY += laneH + 14
  })

  const flowEdges = []
  for (const [fromId, toId] of edgePairs) {
    const src = flowNodeMap.get(fromId)
    const dst = flowNodeMap.get(toId)
    if (!src || !dst) continue
    const x1 = src.x + src.w
    const y1 = src.cy
    const x2 = dst.x
    const y2 = dst.cy
    const dx = Math.max(28, Math.abs(x2 - x1) * 0.45)
    const pathD = `M ${x1} ${y1} C ${x1 + dx} ${y1}, ${x2 - dx} ${y2}, ${x2} ${y2}`
    flowEdges.push({
      id: `flow:${fromId}->${toId}`,
      fromId,
      toId,
      pathD,
      impacted: src.diffState !== 'context' || dst.diffState !== 'context',
    })
  }

  const width = Math.max(640, ...lanes.map((l) => l.w + pad))
  const height = Math.max(280, curY + pad)
  return { width, height, lanes, nodes: flowNodes, edges: flowEdges, flows: flowSummaries }
}

export function buildVisualModel({
  featureMap = {},
  diffOverlay = {},
  mode = 'architecture-map',
  title = '',
  briefSpec = null,
} = {}) {
  const overlay = computeDiffOverlay(featureMap, diffOverlay)
  const tree = layoutDomainTree(featureMap, overlay)
  const flow = layoutFlowDag(featureMap, overlay)
  const repoName = String(featureMap?.repoName || featureMap?.project || briefSpec?.repoName || '项目仓库').trim()
  const resolvedMode = mode === 'visual-brief' ? 'visual-brief' : 'architecture-map'
  const resolvedTitle = String(
    title
    || briefSpec?.title
    || (resolvedMode === 'visual-brief' ? `${repoName} — 实时规划简报` : `${repoName} — 架构全景图`)
  ).trim()

  const verdict = briefSpec?.verdict || {
    status: overlay.hasActiveDiff ? '有变更' : '已同步',
    tone: overlay.hasActiveDiff ? 'warn' : 'pass',
    summary: overlay.hasActiveDiff
      ? `新增 ${overlay.counts.added}、修改 ${overlay.counts.modified}、受波及 ${overlay.counts.impacted} 个模块。`
      : `共 ${tree.domains.length} 个域、${tree.nodes.length} 个模块，全部已同步。`,
  }

  const scopeChips = normArray(briefSpec?.scopeChips).length > 0
    ? normArray(briefSpec.scopeChips)
    : [
        `schema:${featureMap?.version >= 2 ? 'v2' : 'v1-compat'}`,
        `域:${tree.domains.length}`,
        `模块:${tree.nodes.length}`,
        `依赖:${tree.edges.length}`,
      ]

  const metrics = Array.isArray(briefSpec?.metrics) && briefSpec.metrics.length > 0
    ? briefSpec.metrics
    : [
        { label: '域', value: String(tree.domains.length) },
        { label: '模块', value: String(tree.nodes.length) },
        { label: '依赖', value: String(tree.edges.length) },
        { label: '新增', value: String(overlay.counts.added) },
        { label: '修改', value: String(overlay.counts.modified) },
        { label: '受波及', value: String(overlay.counts.impacted) },
      ]

  const walkthrough = Array.isArray(briefSpec?.walkthrough) && briefSpec.walkthrough.length > 0
    ? briefSpec.walkthrough.map((step, idx) => ({
        index: idx,
        targetId: String(step.targetId || tree.nodes[idx]?.id || '').trim(),
        title: String(step.title || `步骤 ${idx + 1}`).trim(),
        detail: String(step.detail || '').trim(),
      }))
    : tree.nodes.map((n, idx) => ({
        index: idx,
        targetId: n.id,
        title: n.title,
        detail: n.description || `${n.domainTitle || n.domain}（${n.modules.length} 个模块，${n.tests.length} 个测试）`,
      }))

  const prototypes = Array.isArray(briefSpec?.prototypes) ? briefSpec.prototypes : []
  const panels = [
    { id: 'panel-tree', title: '架构总览', promptHint: '核查领域边界与模块归属。' },
    { id: 'panel-flow', title: '业务流转', promptHint: '核查跨模块依赖关系与角色泳道。' },
    { id: 'panel-diff', title: '变更影响', promptHint: '核查新增、修改及下游受波及模块。' },
    { id: 'panel-prototypes', title: '方案原型', promptHint: '核查沙盒原型预览与外部设计参考链接。' },
  ]

  return {
    schemaVersion: 2,
    mode: resolvedMode,
    repoName,
    title: resolvedTitle,
    verdict,
    scopeChips,
    metrics,
    overlayCounts: overlay.counts,
    hasActiveDiff: overlay.hasActiveDiff,
    tree,
    flow,
    walkthrough,
    prototypes,
    briefData: briefSpec?.briefData || null,
    panels,
  }
}
